('fairway-finder', 'Fairway Finder', 'driver'::skill_category, 'Pick two targets about 30 yards apart. They''re the edges of your fairway.', array['Driver', '10 balls']::text[], 'Hit 10 drives with your full routine. No do-overs. A drive counts if it finishes between the edges.', array['Fairways hit']::text[], '7', '6', '5', '3', 10, 'higher', 'active', array['driver']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 12, true, null, array['Pick two targets about 30 yards apart. They''re the edges of your fairway.', 'Hit 10 drives with your full routine. No do-overs.', 'A drive counts if it finishes between the edges.']::text[], 'Fairways hit', '{"0-5":7,"6-10":6,"11-15":5,"16-20":4,"21+":3}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"line","x":30,"y":4,"x2":36,"y2":44,"label":"Left edge"},{"k":"line","x":70,"y":4,"x2":64,"y2":44,"label":"Right edge"}],"shots":[{"from":[50,55],"to":[44,10],"air":true},{"from":[50,55],"to":[58,14],"air":true},{"from":[50,55],"to":[76,12],"air":true},{"from":[50,55],"to":[50,8],"air":true}]}'::jsonb, 'test', 'all', 0),
('changing-targets-driver', 'Changing Targets', 'driver'::skill_category, 'Pick three targets: left, middle and right.', array['Driver or fairway wood', '6 balls']::text[], 'Hit 6 drives, choosing a new target before each one. A drive counts if it finishes within about 15 yards of the line you picked.', array['On-target drives']::text[], '5', '4', '3', '2', 6, 'higher', 'active', array['driver']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 10, true, null, array['Pick three targets: left, middle and right.', 'Hit 6 drives, choosing a new target before each one.', 'A drive counts if it finishes within about 15 yards of the line you picked.']::text[], 'On-target drives', '{"0-5":5,"6-10":4,"11-15":3,"16-20":3,"21+":2}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"flag","x":25,"y":10},{"k":"flag","x":50,"y":8},{"k":"flag","x":75,"y":10}],"shots":[{"from":[50,55],"to":[25,12],"air":true},{"from":[50,55],"to":[50,10],"air":true},{"from":[50,55],"to":[74,12],"air":true}]}'::jsonb, 'skill', 'all', 1),
('distance-control-driver', 'Distance Control', 'driver'::skill_category, 'Pick three landing markers: short, medium and long.', array['Driver or fairway wood', '6 balls']::text[], 'Hit 6 drives in order: short, medium, long, then again. Short is a three-quarter swing, long is full. A drive counts if it finishes within about 20 yards of its marker.', array['Drives on distance']::text[], '5', '4', '3', '2', 6, 'higher', 'active', array['driver']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 10, true, null, array['Pick three landing markers: short, medium and long.', 'Hit 6 drives in order: short, medium, long, then again. Short is a three-quarter swing, long is full.', 'A drive counts if it finishes within about 20 yards of its marker.']::text[], 'Drives on distance', '{"0-5":5,"6-10":4,"11-15":3,"16-20":2,"21+":2}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"mark","x":50,"y":34,"label":"Short"},{"k":"mark","x":50,"y":22,"label":"Medium"},{"k":"mark","x":50,"y":10,"label":"Long"}],"shots":[{"from":[50,55],"to":[48,34],"air":true},{"from":[50,55],"to":[52,22],"air":true},{"from":[50,55],"to":[50,10],"air":true}]}'::jsonb, 'skill', 'all', 2),
('max-distance', 'Max Distance', 'driver'::skill_category, 'Hit 5 drives at full speed, but stay in balance.', array['Driver', '5 balls']::text[], 'Use the range yardage signs to judge carry. Your score is your longest carry that stayed between two targets you picked.', array['Longest carry (yards)']::text[], '260', '240', '220', '180', 400, 'higher', 'active', array['driver']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 8, true, null, array['Hit 5 drives at full speed, but stay in balance.', 'Use the range yardage signs to judge carry.', 'Your score is your longest carry that stayed between two targets you picked.']::text[], 'Longest carry (yards)', '{"0-5":260,"6-10":240,"11-15":220,"16-20":200,"21+":180}'::jsonb, '{"set":"range","pose":"finish","items":[{"k":"mark","x":50,"y":30,"label":"200"},{"k":"mark","x":50,"y":18,"label":"250"},{"k":"mark","x":50,"y":6,"label":"300"}],"shots":[{"from":[50,55],"to":[46,20],"air":true},{"from":[50,55],"to":[54,14],"air":true},{"from":[50,55],"to":[50,9],"air":true}]}'::jsonb, 'test', 'all', 3),
('sweet-spot-driver', 'Sweet Spot', 'driver'::skill_category, 'Spray the driver face (or add impact tape).', array['Driver', 'Impact spray or tape', '7 balls']::text[], 'Hit 7 drives. Check the mark after each one, then wipe or re-spray. A drive counts if the mark is in the middle of the face.', array['Center strikes']::text[], '5', '4', '3', '2', 7, 'higher', 'active', array['driver']::text[], array['range', 'net']::text[], 'clubs_balls', array['impact_spray']::text[], 10, true, null, array['Spray the driver face (or add impact tape).', 'Hit 7 drives. Check the mark after each one, then wipe or re-spray.', 'A drive counts if the mark is in the middle of the face.']::text[], 'Center strikes', '{"0-5":5,"6-10":4,"11-15":3,"16-20":2,"21+":2}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"mark","x":50,"y":24,"label":"Check the face"}],"shots":[{"from":[50,55],"to":[50,10],"air":true},{"from":[50,55],"to":[44,14],"air":true}]}'::jsonb, 'skill', 'all', 4),
('proximity-test', 'Proximity Test', 'irons'::skill_category, 'Pick one flag 100 to 150 yards away.', array['One iron', '10 balls']::text[], 'Hit 10 shots at it. 2 points if a ball finishes within 10 yards of the flag, 1 point within 20 yards.', array['Points']::text[], '14', '11', '8', '4', 20, 'higher', 'active', array['irons']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 12, true, null, array['Pick one flag 100 to 150 yards away.', 'Hit 10 shots at it.', '2 points if a ball finishes within 10 yards of the flag, 1 point within 20 yards.']::text[], 'Points', '{"0-5":14,"6-10":11,"11-15":8,"16-20":6,"21+":4}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"zone","x":50,"y":14,"r":7,"label":"10 yds"},{"k":"zone","x":50,"y":14,"r":13,"label":"20 yds"},{"k":"flag","x":50,"y":14}],"shots":[{"from":[50,55],"to":[47,15],"air":true},{"from":[50,55],"to":[56,12],"air":true},{"from":[50,55],"to":[50,22],"air":true}]}'::jsonb, 'test', 'all', 5),
