('towel-strike', 'Towel Strike', 'irons'::skill_category, 'Lay a towel flat behind the ball: 1 inch back at 0–5, 2 in at 6–10, 4 in at 11–15, 6 in at 16–20, 8 in at 21+.', array['Any iron or wedge', 'A towel', '10 balls']::text[], 'Hit 10 shots without touching the towel. A shot counts if you miss the towel and hit the ball first.', array['Clean strikes']::text[], '8', '7', '6', '4', 10, 'higher', 'active', array['irons', 'wedges']::text[], array['range', 'net']::text[], 'clubs_balls', array[]::text[], 10, true, null, array['Lay a towel flat behind the ball: 1 inch back at 0–5, 2 in at 6–10, 4 in at 11–15, 6 in at 16–20, 8 in at 21+.', 'Hit 10 shots without touching the towel.', 'A shot counts if you miss the towel and hit the ball first.']::text[], 'Clean strikes', '{"0-5":8,"6-10":7,"11-15":6,"16-20":5,"21+":4}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"towel","x":44,"y":58,"x2":56,"y2":58,"label":"Towel"}],"shots":[{"from":[50,54],"to":[50,16],"air":true}]}'::jsonb, 'skill', 'all', 8),
('green-hunting', 'Green Hunting', 'irons'::skill_category, 'Pick a target green 120 to 160 yards away.', array['Your irons', '10 balls']::text[], 'Hit 10 shots at it. 2 points if a ball finishes on the green, 1 point if it''s within 10 yards of it.', array['Points']::text[], '13', '10', '8', '4', 20, 'higher', 'active', array['irons']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 12, true, null, array['Pick a target green 120 to 160 yards away.', 'Hit 10 shots at it.', '2 points if a ball finishes on the green, 1 point if it''s within 10 yards of it.']::text[], 'Points', '{"0-5":13,"6-10":10,"11-15":8,"16-20":6,"21+":4}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"zone","x":50,"y":14,"r":9,"label":"Green"},{"k":"flag","x":52,"y":13}],"shots":[{"from":[50,55],"to":[48,14],"air":true},{"from":[50,55],"to":[60,18],"air":true},{"from":[50,55],"to":[40,10],"air":true}]}'::jsonb, 'skill', 'all', 9),
('distance-control-irons', 'Three-Club Ladder', 'irons'::skill_category, 'Give each club its own flag at its normal carry distance.', array['3 irons (like 9, 7 and 5)', '6 balls']::text[], 'Hit 2 shots with each club, switching clubs every shot. A shot counts if it lands within 10 yards of that club''s flag.', array['Shots on distance']::text[], '5', '4', '3', '2', 6, 'higher', 'active', array['irons']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 10, true, null, array['Give each club its own flag at its normal carry distance.', 'Hit 2 shots with each club, switching clubs every shot.', 'A shot counts if it lands within 10 yards of that club''s flag.']::text[], 'Shots on distance', '{"0-5":5,"6-10":4,"11-15":3,"16-20":2,"21+":2}'::jsonb, '{"set":"range","pose":"swing","items":[{"k":"flag","x":40,"y":34,"label":"9i"},{"k":"flag","x":52,"y":22,"label":"7i"},{"k":"flag","x":62,"y":10,"label":"5i"}],"shots":[{"from":[50,55],"to":[40,35],"air":true},{"from":[50,55],"to":[52,23],"air":true},{"from":[50,55],"to":[62,11],"air":true}]}'::jsonb, 'skill', 'all', 10),
