('shot-shape-challenge', 'Shot Shape Challenge', 'irons'::skill_category, 'Call the shape out loud before every swing: draw, fade, high or low.', array['7-iron', '12 balls']::text[], 'Go through all four shapes three times (12 balls). A shot counts if it matches what you called.', array['Shapes matched']::text[], '7', '5', '4', '2', 12, 'higher', 'active', array['irons']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 12, true, null, array['Call the shape out loud before every swing: draw, fade, high or low.', 'Go through all four shapes three times (12 balls).', 'A shot counts if it matches what you called.']::text[], 'Shapes matched', '{"0-5":7,"6-10":5,"11-15":4,"16-20":3,"21+":2}'::jsonb, '{"set":"range","pose":"think","items":[{"k":"flag","x":50,"y":10}],"shots":[{"from":[50,55],"to":[42,12],"air":true},{"from":[50,55],"to":[58,12],"air":true}]}'::jsonb, 'skill', 'advanced', 12),
