('swing-clock', 'Swing Clock', 'wedges'::skill_category, 'Use three backswing lengths: lead arm at 7:30, 9:00 and 10:30 on a clock.', array['A wedge', '9 balls']::text[], 'Hit 3 balls with each length. Note where the first one lands. Each of the next two counts if it lands within 5 yards of the first.', array['Matched distances']::text[], '5', '4', '4', '2', 6, 'higher', 'active', array['wedges']::text[], array['range']::text[], 'clubs_balls', array[]::text[], 10, true, null, array['Use three backswing lengths: lead arm at 7:30, 9:00 and 10:30 on a clock.', 'Hit 3 balls with each length. Note where the first one lands.', 'Each of the next two counts if it lands within 5 yards of the first.']::text[], 'Matched distances', '{"0-5":5,"6-10":4,"11-15":4,"16-20":3,"21+":2}'::jsonb, '{"set":"range","pose":"chip","items":[{"k":"mark","x":50,"y":40,"label":"7:30"},{"k":"mark","x":50,"y":28,"label":"9:00"},{"k":"mark","x":50,"y":16,"label":"10:30"}],"shots":[{"from":[50,55],"to":[50,40],"air":true},{"from":[50,55],"to":[50,28],"air":true},{"from":[50,55],"to":[50,16],"air":true}]}'::jsonb, 'skill', 'all', 15),
('ladder-drill', 'Ladder Drill', 'wedges'::skill_category, 'Hit a short chip, about 10 yards. That''s the first rung.', array['A wedge', 'A pile of balls']::text[], 'Each next ball must land past the last one but stay inside 40 yards. Keep going until one lands short of the last ball or past 40.', array['Balls in a row']::text[], '10', '8', '6', '4', 15, 'higher', 'active', array['wedges']::text[], array['range', 'chip']::text[], 'clubs_balls', array[]::text[], 10, true, null, array['Hit a short chip, about 10 yards. That''s the first rung.', 'Each next ball must land past the last one but stay inside 40 yards.', 'Keep going until one lands short of the last ball or past 40.']::text[], 'Balls in a row', '{"0-5":10,"6-10":8,"11-15":6,"16-20":5,"21+":4}'::jsonb, '{"set":"chip","pose":"chip","items":[{"k":"line","x":20,"y":8,"x2":80,"y2":8,"label":"40 yds"}],"shots":[{"from":[50,55],"to":[50,44],"air":true},{"from":[50,55],"to":[50,36],"air":true},{"from":[50,55],"to":[50,28],"air":true},{"from":[50,55],"to":[50,20],"air":true}]}'::jsonb, 'skill', 'all', 16),
