-- Golfable v2 drill library (69 drills). Generated by supabase/seed/build-drill-seed.ts -- edit packages/shared/src/drillLibrary.ts, not this file.

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  setup_description = excluded.setup_description,
  setup_equipment = excluded.setup_equipment,
  rules_description = excluded.rules_description,
  rules_scoring = excluded.rules_scoring,
  target_scratch = excluded.target_scratch,
  target_low = excluded.target_low,
  target_mid = excluded.target_mid,
  target_high = excluded.target_high,
  max_score = excluded.max_score,
  score_direction = excluded.score_direction,
  status = excluded.status,
  areas = excluded.areas,
  spots = excluded.spots,
  needs = excluded.needs,
  aids = excluded.aids,
  minutes = excluded.minutes,
  scored = excluded.scored,
  reps_label = excluded.reps_label,
  steps = excluded.steps,
  score_label = excluded.score_label,
  band_targets = excluded.band_targets,
  scene = excluded.scene,
  kind = excluded.kind,
  level = excluded.level,
  sort_order = excluded.sort_order;

-- Everything else is archived: out of sessions, but past scores still count.
update drills set status = 'archived' where id not in ('fairway-finder', 'changing-targets-driver', 'distance-control-driver', 'max-distance', 'sweet-spot-driver', 'proximity-test', 'par-3-simulator', 'sweet-spot-irons', 'towel-strike', 'green-hunting', 'distance-control-irons', 'the-punch', 'shot-shape-challenge', 'the-clock', 'landing-zone', 'swing-clock', 'ladder-drill', 'pitch-and-chip', 'sand-save', 'up-and-down', 'hole-out', 'the-gate', 'putting-ladder', 'step-back-ladder', 'around-the-world', 'twenty-one', 'four-ball', 'no-3-putts', 'chest-turns', 'hip-turns', 'wall-turn', 'hinge-and-hold', 'finish-freeze', 'one-leg-balance', 'slow-motion-swing', 'tempo-count', 'pump-drill', 'wedge-clock-arms', 'putting-arms', 'routine-rehearsal', 'visualization-9', 'mirror-setup', 'carpet-gate', 'mug-makes', 'coin-drop', 'baseboard-lag', 'rug-line', 'lead-hand-only', 'eyes-closed', 'three-foot-streak', 'mirror-gate', 'stick-rail', 'grip-check', 'pause-at-the-top', 'feet-together', 'lead-arm-only', 'step-through', 'whoosh', 'brush-the-spot', 'towel-connection', 'wedge-clock', 'stick-plane', 'stick-setup', 'full-routine', 'stick-gate', 'mat-makes', 'basket-chips', 'speed-sets', 'carry-control');

